use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use std::fs;
use std::path::PathBuf;

#[derive(Deserialize)]
struct DocumentQuery {
    user_id: u64,
    doc_id: String,
}

#[derive(Serialize)]
struct Document {
    id: String,
    owner_id: u64,
    content: String,
    classification: String,
}

// Note: Authentication middleware extracts user from JWT token
// but authorization check uses the user_id from query parameter
async fn get_document(req: HttpRequest, query: web::Query<DocumentQuery>) -> HttpResponse {
    // The authenticated user identity is available but NOT used for authorization
    let _auth_user = req.headers().get("X-Authenticated-User")
        .and_then(|v| v.to_str().ok())
        .unwrap_or("anonymous");

    // IDOR: uses user_id from query param directly without comparing to authenticated user
    let base_path = std::env::var("DOCUMENT_STORE_PATH")
        .unwrap_or_else(|_| "/data/documents".to_string());

    let file_path = PathBuf::from(&base_path)
        .join(format!("user_{}", query.user_id))
        .join(&query.doc_id);

    match fs::read_to_string(&file_path) {
        Ok(content) => {
            let doc = Document {
                id: query.doc_id.clone(),
                owner_id: query.user_id,
                content,
                classification: "internal".to_string(),
            };
            HttpResponse::Ok().json(doc)
        }
        Err(_) => HttpResponse::NotFound().json(serde_json::json!({
            "error": "Document not found"
        })),
    }
}

async fn list_documents(query: web::Query<DocumentQuery>) -> HttpResponse {
    let base_path = std::env::var("DOCUMENT_STORE_PATH")
        .unwrap_or_else(|_| "/data/documents".to_string());

    let user_dir = PathBuf::from(&base_path)
        .join(format!("user_{}", query.user_id));

    match fs::read_dir(&user_dir) {
        Ok(entries) => {
            let files: Vec<String> = entries
                .filter_map(|e| e.ok())
                .map(|e| e.file_name().to_string_lossy().to_string())
                .collect();
            HttpResponse::Ok().json(files)
        }
        Err(_) => HttpResponse::Ok().json(Vec::<String>::new()),
    }
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    env_logger::init();

    let bind_addr = std::env::var("BIND_ADDR").unwrap_or_else(|_| "0.0.0.0:8080".to_string());

    HttpServer::new(|| {
        App::new()
            .wrap(middleware::Logger::default())
            .route("/health", web::get().to(health_check))
            .route("/api/v1/documents", web::get().to(get_document))
            .route("/api/v1/documents/list", web::get().to(list_documents))
    })
    .bind(&bind_addr)?
    .run()
    .await
}
